SHOW TABLES LIKE '%risky%';
DESCRIBE entra_risky_signins;
SELECT * FROM entra_risky_signins WHERE ip_address = '107.253.5.27' LIMIT 10;

-- Once the correct table/columns are known, retrieve the exact date/time of the suspicious SAP authentication from that IP
